interface ToolResult {
  isError?: boolean;
  content?: Array<{ type: string; text: string }>;
}

type ToolHandler = (
  input: Record<string, unknown>,
  extra: unknown
) => Promise<ToolResult>;

function createMockServer(): {
  server: ToolRegistrar;
  tools: Record<string, { handler: ToolHandler }>;
} {
