    ) {
      tools[name] = { handler };
    },
  } as ToolRegistrar;
  return { server, tools };
}

function responseJson(result: ToolResult): Record<string, unknown> {
  return JSON.parse(result.content?.[0]?.text ?? "{}") as Record<string, unknown>;
}

