{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.discourse/mcp",
  "description": "Discourse MCP CLI server (stdio) exposing Discourse tools via MCP",
  "repository": {
    "url": "https://github.com/discourse/discourse-mcp",
    "source": "github"
  },
  "version": "0.3.1",
  "packages": [
    {
      "registryType": "npm",
      "identifier": "@discourse/mcp",
      "version": "0.3.1",
      "transport": {
        "type": "stdio"
      }
    }
  ]
}

#!/usr/bin/env node
import { randomUUID } from "node:crypto";
import { readFile } from "node:fs/promises";
import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { StreamableHTTPServerTransport } from "@modelcontextprotocol/sdk/server/streamableHttp.js";
import { z } from "zod";
import { generateUserApiKey, type GenerateOptions } from "./user-api-key-generator.js";

// Read package version at runtime to avoid import-attributes incompatibility
async function getPackageVersion(): Promise<string> {
  try {
    const pkgPath = new URL("../package.json", import.meta.url);
    const raw = await readFile(pkgPath, "utf8");
    const pkg = JSON.parse(raw) as { version?: string };
    return pkg.version || "0.0.0";
  } catch {
    return "0.0.0";
  }
}
import { Logger, type LogLevel } from "./util/logger.js";
import { redactObject } from "./util/redact.js";
import { parseArgs, expandCurrentUserHome } from "./util/cli.js";
import { type AuthMode } from "./http/client.js";
import { registerAllTools, type ToolsMode } from "./tools/registry.js";
import {
  BuiltinToolsetsSchema,
  parseBuiltinToolsets,
} from "./tools/toolsets.js";
import { tryRegisterRemoteTools } from "./tools/remote/tool_exec_api.js";
import { registerAllResources } from "./resources/registry.js";
import { registerAllPrompts } from "./prompts/registry.js";
import { SiteState, type AuthOverride } from "./site/state.js";

const DEFAULT_TIMEOUT_MS = 15000;
const LOOPBACK_HOST = "127.0.0.1";
const MAX_HTTP_BODY_BYTES = 4 * 1024 * 1024;

function topLevelMetadataRequest(args: string[]): "help" | "version" | undefined {
  for (const arg of args) {
    if (arg === "--") break;
    if (arg === "--help" || arg === "-h" || arg === "help") return "help";
    if (arg === "--version" || arg === "-v" || arg === "version") return "version";
  }
}

function helpText(): string {
  return `Discourse MCP server

Usage:
  discourse-mcp [options]
  discourse-mcp generate-user-api-key [options]

Information:
  -h, --help, help                 Show this help and exit
  -v, --version, version           Show the package version and exit

Configuration:
  --profile <path>                 JSON profile (~, ~/ and ~\\ expand for the current user)
  --site <url>                     Tether and preselect one Discourse site
  --auth_pairs <json>              Site-specific API/User API credentials
  --allow_writes <boolean>         Enable mutation tools (default: false)
  --read_only <boolean>            Deprecated: true vetoes writes; false has no effect
  --tools_mode <mode>              auto, discourse_api_only, or tool_exec_api
  --toolsets <domains>             Comma-separated built-in domains or all
                                   Includes opt-in administration, groups, tag_groups,
                                   moderation, workflows, and AI administration domains
  --default-search <prefix>        Prefix applied to every search query
  --max-read-length <number>       Maximum returned post-content characters
  --allowed_upload_paths <paths>   Comma-separated/JSON upload allowlist (no ~ expansion)
  --show_emails <boolean>          Include email fields when authorized
  --transport <stdio|http>         MCP transport (default: stdio)
  --port <number>                  Loopback HTTP port (default: 3000)
  --log_level <level>              silent, error, info, or debug
  --cache_dir <path>               Reserved compatibility option

See README.md for profile, authentication, toolset, and HTTP-session examples.
`;
}

function allowedHttpHosts(port: number): string[] {
  return [`localhost:${port}`, `127.0.0.1:${port}`, `[::1]:${port}`];
}

function allowedHttpOrigins(port: number): string[] {
  return [`http://localhost:${port}`, `http://127.0.0.1:${port}`, `http://[::1]:${port}`];
}

function httpHostError(req: IncomingMessage, port: number): string | undefined {
  const host = req.headers.host;
  if (!host || !allowedHttpHosts(port).includes(host)) {
    return `Invalid Host header: ${host}`;
  }
}

function httpOriginError(req: IncomingMessage, port: number): string | undefined {
  const origin = req.headers.origin;
  if (!origin) {
    return;
  }

  const originHeader = Array.isArray(origin) ? origin[0] : origin;
  if (!allowedHttpOrigins(port).includes(originHeader)) {
    return `Invalid Origin header: ${originHeader}`;
  }
}

function rejectMcpRequest(
  res: ServerResponse,
  message: string,
  status = 403,
  code = -32000,
): void {
  res.writeHead(status, { "Content-Type": "application/json" });
  res.end(
    JSON.stringify({
      jsonrpc: "2.0",
      error: {
        code,
        message,
      },
      id: null,
    })
  );
}

// CLI config schema - see also src/util/cli.ts for parseArgs
const ProfileSchema = z
  .object({
    auth_pairs: z
      .array(
        z
          .object({
            site: z.string().url(),
            api_key: <REDACTED>
            api_username: z.string().optional(),
            user_api_key: <REDACTED>
            user_api_client_id: z.string().optional(),
            http_basic_user: z.string().optional(),
            http_basic_pass: z.string().optional(),
          })
          .strict()
      )
      .optional(),
    read_only: z.boolean().optional(),
    allow_writes: z.boolean().optional().default(false),
    timeout_ms: z.number().int().positive().optional().default(DEFAULT_TIMEOUT_MS),
    concurrency: z.number().int().positive().optional().default(4),
    cache_dir: z.string().optional(),
    log_level: z.enum(["silent", "error", "info", "debug"]).optional().default("info"),
    show_emails: z.boolean().optional().default(false),
    tools_mode: z.enum(["auto", "discourse_api_only", "tool_exec_api"]).optional().default("auto"),
    toolsets: BuiltinToolsetsSchema.optional().describe("Built-in tool domains to expose (array or comma-separated string). Omit for the default catalog; use all to include opt-in workflows and AI administration domains."),
    site: z.string().url().optional().describe("Tether MCP to a single Discourse site; hides select_site and preselects this site"),
    default_search: z.string().optional().describe("Optional search prefix added to every search query (set via --default-search)"),
    max_read_length: z
      .number()
      .int()
      .positive()
      .optional()
      .default(50000)
      .describe("Maximum number of characters to include when returning post content (set via --max-read-length)"),
    transport: z.enum(["stdio", "http"]).optional().default("stdio").describe("Transport type: stdio (default) or http"),
    port: z.number().int().positive().optional().default(3000).describe("Port to listen on when using HTTP transport"),
    allowed_upload_paths: z.union([z.array(z.string()), z.string()])
      .optional()
      .transform((val) => {
        // Normalize to array (parseAllowedUploadPaths handles this, but schema re-validates after merge)
        if (val === undefined) return undefined;
        if (Array.isArray(val)) return val;
        // Comma-separated string
        return val.split(",").map(s => s.trim()).filter(Boolean);
      })
      .describe("Allowed directories for local file uploads (array or comma-separated string)"),
  })
  .strict();

type Profile = z.infer<typeof ProfileSchema>;

async function loadProfile(path?: string): Promise<Partial<Profile>> {
  if (!path) return {};
  const txt = await readFile(expandCurrentUserHome(path), "utf8");
  const raw = JSON.parse(txt);
  const parsed = ProfileSchema.partial().safeParse(raw);
  if (!parsed.success) throw new Error(`Invalid profile JSON: ${parsed.error.message}`);
  return parsed.data;
}

function parseAuthPairs(value: unknown, source: string): AuthOverride[] | undefined {
  if (value === undefined || value === null) return undefined;
  if (Array.isArray(value)) return value as AuthOverride[];
  if (typeof value === "string") {
    const trimmed = value.trim();
    if (!trimmed) return undefined;
    try {
      const parsed = JSON.parse(trimmed);
      if (Array.isArray(parsed)) return parsed as AuthOverride[];
      throw new Error(`auth_pairs ${source} must be a JSON array`);
    } catch (e: any) {
      if (e.message?.includes("auth_pairs")) throw e;
      throw new Error(`Failed to parse auth_pairs ${source} as JSON: ${e.message}`);
    }
  }
  throw new Error(`auth_pairs ${source} must be a JSON array or array value`);
}

function parseAllowedUploadPaths(value: unknown, source: string): string[] | undefined {
  if (value === undefined || value === null) return undefined;
  if (Array.isArray(value)) return value.map(String);
  if (typeof value === "string") {
    const trimmed = value.trim();
    // Try parsing as JSON array first
    if (trimmed.startsWith("[")) {
      try {
        const parsed = JSON.parse(trimmed);
        if (Array.isArray(parsed)) return parsed.map(String);
        throw new Error(`allowed_upload_paths ${source} must be an array, got ${typeof parsed}`);
      } catch (e: any) {
        if (e.message?.includes("allowed_upload_paths")) throw e;
        throw new Error(`Failed to parse allowed_upload_paths ${source} as JSON: ${e.message}`);
      }
    }
    // Parse as comma-separated list
    return value.split(",").map(s => s.trim()).filter(Boolean);
  }
  throw new Error(`allowed_upload_paths ${source} must be a string or array, got ${typeof value}`);
}

function mergeConfig(profile: Partial<Profile>, flags: Record<string, unknown>): Profile {
  const merged = {
    auth_pairs: parseAuthPairs(flags.auth_pairs ?? flags["auth-pairs"], "from CLI") ?? parseAuthPairs(profile.auth_pairs, "from profile"),
    read_only: ((flags.read_only ?? flags["read-only"]) as boolean | undefined) ?? profile.read_only,
    allow_writes: ((flags.allow_writes ?? flags["allow-writes"]) as boolean | undefined) ?? profile.allow_writes ?? false,
    timeout_ms: ((flags.timeout_ms ?? flags["timeout-ms"]) as number | undefined) ?? profile.timeout_ms ?? DEFAULT_TIMEOUT_MS,
    concurrency: (flags.concurrency as number | undefined) ?? profile.concurrency ?? 4,
    cache_dir: ((flags.cache_dir ?? flags["cache-dir"]) as string | undefined) ?? profile.cache_dir,
    log_level: (((flags.log_level ?? flags["log-level"]) as LogLevel | undefined) ?? (profile.log_level as LogLevel | undefined) ?? "info") as LogLevel,
    show_emails: (((flags.show_emails ?? flags["show-emails"]) as boolean | undefined) ?? (profile.show_emails as boolean | undefined) ?? false) as boolean,
    tools_mode: (((flags.tools_mode ?? flags["tools-mode"]) as ToolsMode | undefined) ?? (profile.tools_mode as ToolsMode | undefined) ?? "auto") as ToolsMode,
    toolsets: parseBuiltinToolsets(flags.toolsets, "from CLI") ?? profile.toolsets,
    site: (flags.site as string | undefined) ?? profile.site,
    default_search: (((flags.default_search ?? flags["default-search"]) as string | undefined) ?? profile.default_search) as string | undefined,
    max_read_length: (((flags.max_read_length ?? flags["max-read-length"]) as number | undefined) ?? profile.max_read_length ?? 50000) as number,
    transport: ((flags.transport as "stdio" | "http" | undefined) ?? profile.transport ?? "stdio") as "stdio" | "http",
    port: ((flags.port as number | undefined) ?? profile.port ?? 3000) as number,
    allowed_upload_paths: parseAllowedUploadPaths(flags.allowed_upload_paths ?? flags["allowed-upload-paths"], "from CLI") ?? parseAllowedUploadPaths(profile.allowed_upload_paths, "from profile"),
  } satisfies Profile;
  const result = ProfileSchema.safeParse(merged);
  if (!result.success) throw new Error(`Invalid configuration: ${result.error.message}`);
  if (result.data.allow_writes && result.data.read_only === true) {
    throw new Error("Invalid configuration: allow_writes=true conflicts with read_only=true (from CLI or profile); remove read_only=true to enable writes, or remove allow_writes=true to remain read-only");
  }
  return result.data;
}

function buildAuth(_config: Profile): AuthMode {
  // Global default is no auth; use per-site overrides via auth_pairs when provided
  return { type: "none" };
}

async function main() {
  // Check if user wants to generate a User API Key
  const args = process.argv.slice(2);
  if (args[0] === "generate-user-api-key") {
    // Use rawStrings to preserve nonce/payload values (e.g., leading zeros in numeric strings)
    const subArgs = parseArgs(args.slice(1), { rawStrings: true });

    // Show help if requested
    if (subArgs.help || subArgs.h) {
      await generateUserApiKey({ site: "" }); // Will show help and exit
      return;
    }

    // Map parsed args to GenerateOptions (kebab-case CLI to camelCase options)
    // All values are already strings due to rawStrings option
    const options: GenerateOptions = {
      site: (subArgs.site as string) ?? "",
      scopes: subArgs.scopes as string | undefined,
      applicationName: subArgs["application-name"] as string | undefined,
      clientId: subArgs["client-id"] as string | undefined,
      nonce: subArgs.nonce as string | undefined,
      payload: subArgs.payload as string | undefined,
      saveTo: subArgs["save-to"] as string | undefined,
    };

    await generateUserApiKey(options);
    return;
  }

  const metadata = topLevelMetadataRequest(args);
  if (metadata === "help") {
    process.stdout.write(helpText());
    return;
  }
  if (metadata === "version") {
    process.stdout.write(`${await getPackageVersion()}\n`);
    return;
  }

  const argv = parseArgs(args);
  const profilePath = (argv.profile as string | undefined) ?? undefined;
  const profile = await loadProfile(profilePath).catch((e) => {
    throw new Error(`Failed to load profile: ${e?.message || String(e)}`);
  });
  const config = mergeConfig(profile, argv);

  const logger = new Logger(config.log_level);
  if (config.read_only === false) {
    logger.info("Deprecated configuration: read_only=false is no longer required and has no effect; use allow_writes=true to enable mutation tools.");
  }
  const auth = buildAuth(config);

  // Meta log (stderr) without leaking secrets
  const version = await getPackageVersion();
  logger.info(`Starting Discourse MCP v${version}`);
  logger.debug(`Config: ${JSON.stringify(redactObject({ ...config }))}`);

  // Initialize dynamic site state
  const authOverrides = Array.isArray(config.auth_pairs)
    ? (config.auth_pairs as unknown as AuthOverride[])
    : undefined;
  const siteState = new SiteState({
    logger,
    timeoutMs: config.timeout_ms,
    defaultAuth: auth,
    authOverrides,
  });

  const server = new McpServer(
    {
      name: "@discourse/mcp",
      version,
    },
    {
      capabilities: {
        tools: { listChanged: false },
        resources: { listChanged: false },
        prompts: { listChanged: false },
      },
    }
  );

  const allowWrites = Boolean(config.allow_writes);
  const showEmails = Boolean(config.show_emails);

  // If tethered to a site, validate and preselect it before registering tools,
  // and trigger remote tool discovery when enabled.
  let hideSelectSite = false;
  if (config.site) {
    try {
      const { base, client } = siteState.buildClientForSite(config.site);
      const about = (await client.get(`/about.json`)) as any;
      const title = about?.about?.title || about?.title || base;
      siteState.selectSite(base);
      hideSelectSite = true;
      logger.info(`Tethered to site: ${base} (${title})`);
    } catch (e: any) {
      throw new Error(`Failed to validate --site ${config.site}: ${e?.message || String(e)}`);
    }
  }

  await registerAllTools(server, siteState, logger, {
    allowWrites,
    toolsMode: config.tools_mode,
    toolsets: config.toolsets,
    hideSelectSite,
    defaultSearchPrefix: config.default_search,
    maxReadLength: config.max_read_length,
    allowedUploadPaths: config.allowed_upload_paths,
    showEmails
  });

  // Register MCP resources (URI-addressable read-only data)
  registerAllResources(server, { siteState, logger }, { toolsets: config.toolsets });

  // Register MCP prompts (guided workflows)
  registerAllPrompts(server, { siteState, logger });

  // If tethered and remote tool discovery is enabled, discover now
  if (config.site && config.tools_mode !== "discourse_api_only") {
    await tryRegisterRemoteTools(server, siteState, logger);
  }

  // Create transport based on configuration
  if (config.transport === "http") {
    // Keep one stateful transport so MCP lifecycle and dynamic tool registrations
    // persist for exactly one connected local client. After DELETE the process
    // remains up only to return an explicit restart-required response.
    let sessionClosed = false;
    const transport = new StreamableHTTPServerTransport({
      sessionIdGenerator: randomUUID,
      enableJsonResponse: true,
      enableDnsRebindingProtection: true,
      allowedHosts: allowedHttpHosts(config.port),
      allowedOrigins: allowedHttpOrigins(config.port),
      onsessionclosed: () => {
        sessionClosed = true;
      },
    });

    await server.connect(transport);

    const httpServer = createServer(async (req, res) => {
      // Health check endpoint
      if (req.method === "GET" && req.url === "/health") {
        res.writeHead(sessionClosed ? 503 : 200, { "Content-Type": "application/json" });
        res.end(JSON.stringify(sessionClosed
          ? { status: "restart_required", message: "The single supported MCP session has closed; restart the process for a new client." }
          : { status: "ok", session_model: "single_client" }));
        return;
      }

      // MCP endpoint - handle via StreamableHTTPServerTransport
      if (req.url === "/mcp" || req.url === "/") {
        const headerError = httpHostError(req, config.port) ?? httpOriginError(req, config.port);
        if (headerError) {
          rejectMcpRequest(res, headerError);
          return;
        }

        if (sessionClosed) {
          rejectMcpRequest(
            res,
            "The single supported MCP session is closed; restart the Discourse MCP process before connecting a new client.",
            410,
            -32001,
          );
          return;
        }

        try {
          const chunks: Buffer[] = [];
          let bodyBytes = 0;
          for await (const chunk of req) {
            const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
            bodyBytes += buffer.byteLength;
            if (bodyBytes > MAX_HTTP_BODY_BYTES) {
              rejectMcpRequest(res, `MCP request body exceeds ${MAX_HTTP_BODY_BYTES} bytes`, 413, -32000);
              return;
            }
            chunks.push(buffer);
          }
          const body = chunks.length ? Buffer.concat(chunks).toString("utf8") : "";
          const parsedBody = body ? JSON.parse(body) : undefined;
          await transport.handleRequest(req, res, parsedBody);
        } catch (error) {
          const syntaxError = error instanceof SyntaxError;
          logger.error(`Request handling error: ${syntaxError ? "invalid JSON" : error}`);
          if (!res.headersSent) {
            rejectMcpRequest(
              res,
              syntaxError ? "Parse error: invalid JSON" : "Internal request handling error",
              syntaxError ? 400 : 500,
              syntaxError ? -32700 : -32603,
            );
          }
        }
        return;
      }

      // Unknown endpoint
      res.writeHead(404, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ error: "Not found" }));
    });

    httpServer.listen(config.port, LOOPBACK_HOST, () => {
      logger.info(`HTTP transport listening on ${LOOPBACK_HOST}:${config.port}`);
      logger.info(`Health check available at http://localhost:${config.port}/health`);
      logger.info(`MCP endpoint available at http://localhost:${config.port}/mcp`);
    });

    // Exit cleanly on SIGTERM/SIGINT and close transport streams before the
    // HTTP listener so an active MCP request cannot keep shutdown wedged.
    let shuttingDown = false;
    const onExit = async () => {
      if (shuttingDown) return;
      shuttingDown = true;
      await transport.close().catch((error) => logger.error(`Transport close error: ${error}`));
      httpServer.close(() => {
        logger.info("HTTP server closed");
        process.exit(0);
      });
    };
    process.on("SIGTERM", onExit);
    process.on("SIGINT", onExit);
  } else {
    // Default stdio transport
    const transport = new StdioServerTransport();

    // Exit cleanly on stdin close or signals.
    let shuttingDown = false;
    const onExit = async () => {
      if (shuttingDown) return;
      shuttingDown = true;
      await transport.close().catch(() => undefined);
      process.exit(0);
    };
    process.on("SIGTERM", onExit);
    process.on("SIGINT", onExit);
    process.stdin.on("close", onExit);

    await server.connect(transport);
  }
}

main().catch((err) => {
  const msg = err?.message || String(err);
  process.stderr.write(`[${new Date().toISOString()}] ERROR ${msg}\n`);
  process.exit(1);
});

#!/usr/bin/env node
import { constants, generateKeyPairSync, privateDecrypt, randomBytes } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import { createInterface } from "node:readline";

interface KeyPair {
  publicKey: string;
  privateKey: string;
}

export interface GenerateOptions {
  site: string;
  scopes?: string;
  applicationName?: string;
  clientId?: string;
  nonce?: string;
  payload?: string;
  saveTo?: string;
}

export interface DeviceAuthorization {
  deviceCode: string;
  userCode: string;
  verificationUri: string;
  verificationUriWithRequest?: string;
  expiresIn: number;
  interval: number;
}

interface DecryptedPayload {
  key: string;
  nonce: string;
  push?: boolean;
  api?: number;
  expires_at?: string;
}

type Fetch = typeof fetch;
type Sleep = (milliseconds: number) => Promise<void>;

const DEFAULT_APPLICATION_NAME = "Discourse MCP";
const DEFAULT_CLIENT_ID = "discourse-mcp";
const DEFAULT_SCOPES = "read,write";
const DEVICE_AUTH_HEADER = "Auth-Api-Device-Code";

function siteUrl(site: string, path: string): URL {
  return new URL(`${site.replace(/\/+$/, "")}${path}`);
}

function generateKeyPair(): KeyPair {
  const { publicKey, privateKey } = generateKeyPairSync("rsa", {
    modulusLength: 2048,
    publicKeyEncoding: {
      type: "spki",
      format: "pem",
    },
    privateKeyEncoding: {
      type: "pkcs8",
      format: "pem",
    },
  });

  return { publicKey, privateKey };
}

export function buildAuthorizationUrl(
  options: GenerateOptions,
  publicKey: string,
  nonce: string
): string {
  const url = siteUrl(options.site, "/user-api-key/new");
  url.search = new URLSearchParams({
    application_name: options.applicationName || DEFAULT_APPLICATION_NAME,
    client_id: options.clientId || DEFAULT_CLIENT_ID,
    scopes: options.scopes || DEFAULT_SCOPES,
    public_key: publicKey,
    nonce,
  }).toString();
  return url.toString();
}

export function decryptPayload(
  encryptedPayload: string,
  privateKey: string,
  padding: "pkcs1" | "oaep"
): DecryptedPayload {
  try {
    const buffer = Buffer.from(encryptedPayload, "base64");
    const decrypted = privateDecrypt(
      {
        key: privateKey,
        padding:
          padding === "oaep" ? constants.RSA_PKCS1_OAEP_PADDING : constants.RSA_PKCS1_PADDING,
      },
      buffer
    );
    const result = JSON.parse(decrypted.toString("utf8")) as Partial<DecryptedPayload>;
    if (typeof result.key !== "string" || !result.key) {
      throw new Error("missing 'key' field");
    }
    if (typeof result.nonce !== "string") {
      throw new Error("missing 'nonce' field");
    }
    return result as DecryptedPayload;
  } catch (error: any) {
    throw new Error(`Failed to decrypt payload: ${error?.message || String(error)}`);
  }
}

async function responseError(response: Response): Promise<Error> {
  const body = await response.text().catch(() => "");
  const detail = body ? `: ${body}` : "";
  return new Error(`Request failed with HTTP ${response.status}${detail}`);
}

export async function supportsDeviceAuthorization(
  site: string,
  fetchImpl: Fetch = fetch
): Promise<boolean> {
  const response = await fetchImpl(siteUrl(site, "/user-api-key/new"), { method: "HEAD" });
  if (response.status === 404 || response.status === 405) return false;
  if (!response.ok) throw await responseError(response);
  return response.headers.get(DEVICE_AUTH_HEADER)?.toLowerCase() === "true";
}

export async function createDeviceAuthorization(
  options: GenerateOptions,
  publicKey: string,
  nonce: string,
  fetchImpl: Fetch = fetch
): Promise<DeviceAuthorization> {
  const response = await fetchImpl(siteUrl(options.site, "/user-api-key/device.json"), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      application_name: options.applicationName || DEFAULT_APPLICATION_NAME,
      client_id: options.clientId || DEFAULT_CLIENT_ID,
      scopes: options.scopes || DEFAULT_SCOPES,
      public_key: publicKey,
      nonce,
      padding: "oaep",
    }),
  });
  if (!response.ok) throw await responseError(response);

  const body = (await response.json()) as Record<string, unknown>;
  const validVerificationUri =
    typeof body.verification_uri === "string" && URL.canParse(body.verification_uri);
  const validRequestUri =
    body.verification_uri_with_request === undefined ||
    (typeof body.verification_uri_with_request === "string" &&
      URL.canParse(body.verification_uri_with_request));
  if (
    typeof body.device_code !== "string" ||
    !/^[a-f\d]{64}$/i.test(body.device_code) ||
    typeof body.user_code !== "string" ||
    !/^[A-Z2-9]{4}-[A-Z2-9]{4}$/.test(body.user_code) ||
    !validVerificationUri ||
    !validRequestUri ||
    typeof body.expires_in !== "number" ||
    !Number.isFinite(body.expires_in) ||
    body.expires_in <= 0 ||
    typeof body.interval !== "number" ||
    !Number.isFinite(body.interval) ||
    body.interval <= 0
  ) {
    throw new Error("Invalid device authorization response");
  }

  return {
    deviceCode: body.device_code,
    userCode: body.user_code,
    verificationUri: body.verification_uri as string,
    verificationUriWithRequest:
      typeof body.verification_uri_with_request === "string"
        ? body.verification_uri_with_request
        : undefined,
    expiresIn: body.expires_in,
    interval: body.interval,
  };
}

export async function pollDeviceAuthorization(
  site: string,
  authorization: DeviceAuthorization,
  fetchImpl: Fetch = fetch,
  sleep: Sleep = (milliseconds) => new Promise((resolve) => setTimeout(resolve, milliseconds))
): Promise<string> {
  const deadline = Date.now() + authorization.expiresIn * 1000;
  const interval = Math.max(1, authorization.interval) * 1000;

  while (Date.now() < deadline) {
    const response = await fetchImpl(siteUrl(site, "/user-api-key/device/poll.json"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ device_code: authorization.deviceCode }),
    });
    if (!response.ok) throw await responseError(response);

    const body = (await response.json()) as Record<string, unknown>;
    switch (body.status) {
      case "authorization_pending":
        await sleep(interval);
        break;
      case "authorized":
        if (typeof body.payload !== "string" || !body.payload) {
          throw new Error("Invalid authorized response: missing payload");
        }
        return body.payload;
      case "access_denied":
        throw new Error("The authorization request was denied");
      case "expired_token":
        throw new Error("The authorization request expired");
      default:
        throw new Error(`Unexpected device authorization status: ${String(body.status)}`);
    }
  }

  throw new Error("Timed out waiting for authorization");
}

async function promptForInput(question: string): Promise<string> {
  const rl = createInterface({ input: process.stdin, output: process.stdout });
  return new Promise((resolve) => {
    rl.question(question, (answer) => {
      rl.close();
      resolve(answer.trim());
    });
  });
}

async function saveToProfile(
  profilePath: string,
  site: string,
  userApiKey: <REDACTED>
  clientId: string
): Promise<void> {
  let profile: any = {};

  try {
    const content = await readFile(profilePath, "utf8");
    profile = JSON.parse(content);
  } catch {
    // File doesn't exist or is invalid, start fresh
  }

  if (!profile.auth_pairs) {
    profile.auth_pairs = [];
  }

  // Remove any existing entry for this site
  profile.auth_pairs = profile.auth_pairs.filter((pair: any) => pair.site !== site);

  // Add new entry
  profile.auth_pairs.push({
    site,
    user_api_key: <REDACTED>
    user_api_client_id: clientId,
  });

  await writeFile(profilePath, JSON.stringify(profile, null, 2), "utf8");
}

async function getLegacyPayload(
  options: GenerateOptions,
  publicKey: string,
  nonce: string
): Promise<string> {
  const authUrl = buildAuthorizationUrl(options, publicKey, nonce);
  console.error("This Discourse site does not support device authorization.");
  console.error("Please visit this URL to authorize the application:\n");
  console.error(authUrl);
  console.error("");

  if (options.payload) return options.payload;

  console.error("After authorizing, copy the encrypted payload displayed by Discourse.\n");
  const payload = await promptForInput("Paste the encrypted payload here: ");
  if (!payload) throw new Error("No payload provided");
  return payload;
}

export async function generateUserApiKey(options: GenerateOptions): Promise<void> {
  if (!options.site) {
    console.error(`
Usage: discourse-mcp generate-user-api-key [options]

Options:
  --site <url>              Discourse site URL (required)
  --scopes <scopes>         Comma-separated scopes (default: read,write)
  --application-name <name> Application name (default: Discourse MCP)
  --client-id <id>          Client ID (default: discourse-mcp)
  --nonce <nonce>           Nonce for request (default: random)
  --payload <payload>       Use a legacy encrypted payload directly
  --save-to <file>          Save to profile file instead of printing
  --help, -h                Show this help message

Examples:
  discourse-mcp generate-user-api-key --site https://discourse.example.com
  discourse-mcp generate-user-api-key --site https://discourse.example.com --save-to profile.json
`);
    process.exit(1);
  }

  console.error("\n🔑 Discourse User API Key Generator\n");
  console.error(`Site: ${options.site}`);
  console.error(`Scopes: ${options.scopes || DEFAULT_SCOPES}\n`);
  console.error("Generating RSA key pair...");
  const { publicKey, privateKey } = generateKeyPair();
  const nonce = options.nonce || randomBytes(32).toString("hex");
  console.error("✓ Key pair generated\n");

  let encryptedPayload: string;
  let padding: "pkcs1" | "oaep";

  if (!options.payload && (await supportsDeviceAuthorization(options.site))) {
    console.error("Requesting device authorization...");
    const authorization = await createDeviceAuthorization(options, publicKey, nonce);
    const verificationUri =
      authorization.verificationUriWithRequest || authorization.verificationUri;
    console.error("\nOpen this URL in your browser:\n");
    console.error(verificationUri);
    console.error(`\nEnter this code when prompted: ${authorization.userCode}`);
    console.error("\nWaiting for authorization...");
    encryptedPayload = await pollDeviceAuthorization(options.site, authorization);
    padding = "oaep";
  } else {
    encryptedPayload = await getLegacyPayload(options, publicKey, nonce);
    padding = "pkcs1";
  }

  console.error("\nDecrypting payload...");
  const result = decryptPayload(encryptedPayload, privateKey, padding);
  if (result.nonce !== nonce) {
    throw new Error("Invalid response: nonce did not match the authorization request");
  }
  console.error("✓ User API Key retrieved successfully\n");

  const clientId = options.clientId || DEFAULT_CLIENT_ID;
  if (options.saveTo) {
    await saveToProfile(options.saveTo, options.site, result.key, clientId);
    console.error(`✓ Saved to profile: ${options.saveTo}\n`);
    console.log(JSON.stringify({ success: true, profile: options.saveTo }, null, 2));
  } else {
    console.error("Add this to your auth_pairs configuration:\n");
    console.log(
      JSON.stringify(
        {
          site: options.site,
          user_api_key: <REDACTED>
          user_api_client_id: clientId,
        },
        null,
        2
      )
    );
    console.error("\nOr use --save-to <profile.json> to save automatically.");
  }
}

async function main() {
  const args = process.argv.slice(2);
  const options: GenerateOptions = { site: "" };

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    const next = args[i + 1];

    switch (arg) {
      case "--site":
        options.site = next;
        i++;
        break;
      case "--scopes":
        options.scopes = next;
        i++;
        break;
      case "--application-name":
        options.applicationName = next;
        i++;
        break;
      case "--client-id":
        options.clientId = next;
        i++;
        break;
      case "--nonce":
        options.nonce = next;
        i++;
        break;
      case "--payload":
        options.payload = next;
        i++;
        break;
      case "--save-to":
        options.saveTo = next;
        i++;
        break;
    }
  }

  try {
    await generateUserApiKey(options);
  } catch (error: any) {
    console.error(`\n❌ Error: ${error?.message || String(error)}`);
    process.exit(1);
  }
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch((error) => {
    console.error(`Fatal error: ${error}`);
    process.exit(1);
  });
}

#!/usr/bin/env node
/*
  Sync Discourse fixtures from try.discourse.org.
  Writes JSON files under fixtures/try and a manifest.json for tests.
*/

import { mkdir, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const BASE = process.env.DISCOURSE_SITE || "https://try.discourse.org";
const OUT_DIR = path.resolve(__dirname, "../fixtures/try");

async function main() {
  await mkdir(OUT_DIR, { recursive: true });
  const manifest = { topics: [], posts: [], users: [], queries: [] };

  // site.json
  await fetchAndSave("/site.json", "site.json");

  // tags.json (may be empty on some sites)
  await fetchAndSave("/tags.json", "tags.json");

  // latest topics
  const latest = await fetchJson("/latest.json");
  const topics = Array.isArray(latest?.topic_list?.topics)
    ? latest.topic_list.topics.slice(0, 5)
    : [];
  for (const t of topics) {
    const topicId = t.id;
    const topicFile = `t_${topicId}.json`;
    const topic = await fetchAndSave(`/t/${topicId}.json`, topicFile);
    if (topicId) manifest.topics.push(topicId);
    const firstPostId = topic?.post_stream?.posts?.[0]?.id;
    if (firstPostId) {
      await fetchAndSave(
        `/posts/${firstPostId}.json`,
        `post_${firstPostId}.json`,
      );
      manifest.posts.push(firstPostId);
    }
  }

  // directory users – pick up to 3
  try {
    const dir = await fetchJson(
      "/directory_items.json?period=all&order=likes_received",
    );
    const items = Array.isArray(dir?.directory_items)
      ? dir.directory_items.slice(0, 3)
      : [];
    for (const it of items) {
      const username = it?.user?.username;
      if (!username) continue;
      await fetchAndSave(
        `/u/${encodeURIComponent(username)}.json`,
        `u_${username}.json`,
      );
      manifest.users.push(username);
    }
  } catch (e) {
    // ignore directory errors
  }

  // search queries
  const queries = ["discourse", "welcome"];
  for (const q of queries) {
    const url = `/search.json?expanded=true&q=${encodeURIComponent(q)}`;
    await fetchAndSave(url, `search_${encodeURIComponent(q)}.json`);
    manifest.queries.push(q);
  }

  await writeFile(
    path.join(OUT_DIR, "manifest.json"),
    JSON.stringify(manifest, null, 2),
  );
  process.stderr.write(`[sync-fixtures] Wrote fixtures to ${OUT_DIR}\n`);
}

async function fetchAndSave(p, filename) {
  const data = await fetchJson(p);
  await writeFile(path.join(OUT_DIR, filename), JSON.stringify(data, null, 2));
  return data;
}

async function fetchJson(p) {
  const url = new URL(p, BASE).toString();
  const res = await fetch(url, {
    headers: {
      Accept: "application/json",
      "User-Agent": "Discourse-MCP-Fixtures/0.x",
    },
  });
  if (!res.ok) throw new Error(`HTTP ${res.status} for ${url}`);
  return res.json();
}

if (import.meta.url === `file://${__filename}`) {
  main().catch((err) => {
    process.stderr.write(
      `[sync-fixtures] ERROR ${err?.message || String(err)}\n`,
    );
    process.exit(1);
  });
}

import assert from "node:assert/strict";
import { generateKeyPairSync, publicEncrypt, constants } from "node:crypto";
import test from "node:test";
import {
  buildAuthorizationUrl,
  createDeviceAuthorization,
  decryptPayload,
  pollDeviceAuthorization,
  supportsDeviceAuthorization,
  type GenerateOptions,
} from "../user-api-key-generator.js";

const options: GenerateOptions = {
  site: "https://forum.example/",
  applicationName: "Test CLI",
  clientId: "test-client",
  scopes: "read,write",
};

function mockFetch(
  handler: (url: URL, init?: RequestInit) => Response | Promise<Response>
): typeof fetch {
  return ((input: string | URL | Request, init?: RequestInit) => {
    const url = input instanceof Request ? new URL(input.url) : new URL(input.toString());
    return Promise.resolve(handler(url, init));
  }) as typeof fetch;
}

test("supportsDeviceAuthorization detects the capability header", async () => {
  const supported = await supportsDeviceAuthorization(
    options.site,
    mockFetch((url, init) => {
      assert.equal(url.toString(), "https://forum.example/user-api-key/new");
      assert.equal(init?.method, "HEAD");
      return new Response(null, { headers: { "Auth-Api-Device-Code": "true" } });
    })
  );

  assert.equal(supported, true);
});

test("supportsDeviceAuthorization falls back when the capability is absent", async () => {
  const supported = await supportsDeviceAuthorization(
    options.site,
    mockFetch(() => new Response(null, { status: 200 }))
  );
  assert.equal(supported, false);
});

test("createDeviceAuthorization sends the device protocol request", async () => {
  const authorization = await createDeviceAuthorization(
    options,
    "PUBLIC KEY",
    "request-nonce",
    mockFetch(async (url, init) => {
      assert.equal(url.toString(), "https://forum.example/user-api-key/device.json");
      assert.equal(init?.method, "POST");
      assert.deepEqual(init?.headers, { "Content-Type": "application/json" });
      assert.deepEqual(JSON.parse(String(init?.body)), {
        application_name: "Test CLI",
        client_id: "test-client",
        scopes: "read,write",
        public_key: "PUBLIC KEY",
        nonce: "request-nonce",
        padding: "oaep",
      });
      return Response.json({
        device_code: "a".repeat(64),
        user_code: "ABCD-2345",
        verification_uri: "https://forum.example/user-api-key/activate",
        verification_uri_with_request:
          "https://forum.example/user-api-key/activate?request=abcd1234",
        expires_in: 600,
        interval: 5,
      });
    })
  );

  assert.deepEqual(authorization, {
    deviceCode: "a".repeat(64),
    userCode: "ABCD-2345",
    verificationUri: "https://forum.example/user-api-key/activate",
    verificationUriWithRequest:
      "https://forum.example/user-api-key/activate?request=abcd1234",
    expiresIn: 600,
    interval: 5,
  });
});

test("createDeviceAuthorization rejects malformed protocol responses", async () => {
  await assert.rejects(
    createDeviceAuthorization(
      options,
      "PUBLIC KEY",
      "request-nonce",
      mockFetch(() =>
        Response.json({
          device_code: "too-short",
          user_code: "1234-5678",
          verification_uri: "not a URL",
          expires_in: 600,
          interval: 5,
        })
      )
    ),
    /Invalid device authorization response/
  );
});

test("pollDeviceAuthorization waits through pending and returns the encrypted payload", async () => {
  const statuses = [
    { status: "authorization_pending" },
    { status: "authorized", payload: "encrypted-result" },
  ];
  const sleeps: number[] = [];
  let requests = 0;

  const payload = await pollDeviceAuthorization(
    options.site,
    {
      deviceCode: "b".repeat(64),
      userCode: "WXYZ-6789",
      verificationUri: "https://forum.example/user-api-key/activate",
      expiresIn: 600,
      interval: 5,
    },
    mockFetch(async (url, init) => {
      assert.equal(url.toString(), "https://forum.example/user-api-key/device/poll.json");
      assert.deepEqual(JSON.parse(String(init?.body)), { device_code: "b".repeat(64) });
      return Response.json(statuses[requests++]);
    }),
    async (milliseconds) => {
      sleeps.push(milliseconds);
    }
  );

  assert.equal(payload, "encrypted-result");
  assert.deepEqual(sleeps, [5000]);
  assert.equal(requests, 2);
});

test("pollDeviceAuthorization reports denial", async () => {
  await assert.rejects(
    pollDeviceAuthorization(
      options.site,
      {
        deviceCode: "c".repeat(64),
        userCode: "ABCD-2345",
        verificationUri: "https://forum.example/user-api-key/activate",
        expiresIn: 600,
        interval: 5,
      },
      mockFetch(() => Response.json({ status: "access_denied" })),
      async () => undefined
    ),
    /authorization request was denied/
  );
});

test("decryptPayload decrypts an OAEP response", () => {
  const { publicKey, privateKey } = generateKeyPairSync("rsa", {
    modulusLength: 2048,
    publicKeyEncoding: { type: "spki", format: "pem" },
    privateKeyEncoding: { type: "pkcs8", format: "pem" },
  });
  const plaintext = JSON.stringify({ key: "secret-key", nonce: "request-nonce", api: 4 });
  const encrypted = publicEncrypt(
    { key: publicKey, padding: constants.RSA_PKCS1_OAEP_PADDING },
    Buffer.from(plaintext)
  ).toString("base64");

  assert.deepEqual(decryptPayload(encrypted, privateKey, "oaep"), {
    key: "secret-key",
    nonce: "request-nonce",
    api: 4,
  });
});

test("buildAuthorizationUrl preserves the legacy fallback protocol and site subfolder", () => {
  const url = new URL(
    buildAuthorizationUrl({ ...options, site: "https://forum.example/community/" }, "PUBLIC KEY", "request-nonce")
  );

  assert.equal(url.origin, "https://forum.example");
  assert.equal(url.pathname, "/community/user-api-key/new");
  assert.equal(url.searchParams.get("application_name"), "Test CLI");
  assert.equal(url.searchParams.get("client_id"), "test-client");
  assert.equal(url.searchParams.get("scopes"), "read,write");
  assert.equal(url.searchParams.get("public_key"), "PUBLIC KEY");
  assert.equal(url.searchParams.get("nonce"), "request-nonce");
});

import test from "node:test";
import assert from "node:assert/strict";
import { applyWorkflowOperations, assertPairedGraph, toConnectionList, toNestedConnections } from "../tools/builtin/workflows/graph.js";

test("flat workflow connections convert to nested wire format and round trip", () => {
  const nested = toNestedConnections([{ from: "Start", to: "Check", type: "main", output_index: 0, input_index: 0 }]);
  assert.deepEqual(nested, { Start: { main: [[{ node: "Check", type: "main", index: 0 }]] } });
  assert.deepEqual(toConnectionList(nested), [{ from: "Start", to: "Check", type: "main", output_index: 0, input_index: 0 }]);
});

test("workflow graph fields must be paired", () => {
  assert.throws(() => assertPairedGraph([], undefined), /provided together/);
  assert.throws(() => assertPairedGraph(undefined, {}), /provided together/);
  assert.doesNotThrow(() => assertPairedGraph([], {}));
  assert.doesNotThrow(() => assertPairedGraph(undefined, undefined));
});

test("workflow operations add, connect, and rename nodes mechanically", () => {
  const result = applyWorkflowOperations(
    [{ id: "a", name: "Start", type: "trigger:manual" }], {},
    [
      { op: "add_node", id: "b", node: { name: "Check", type: "condition:if" } },
      { op: "add_connection", from: "a", to: "b", type: "true" },
      { op: "rename_node", id: "b", name: "Renamed" },
    ],
  );
  assert.equal(result.nodes[1].name, "Renamed");
  assert.deepEqual(toConnectionList(result.connections), [{ from: "Start", to: "Renamed", type: "true", output_index: 0, input_index: 0 }]);
});

test("workflow operations reject unresolved node references", () => {
  assert.throws(() => applyWorkflowOperations([], {}, [{ op: "add_connection", from: "missing", to: "also-missing" }]), /resolve workflow node/);
});

import test from "node:test";
import assert from "node:assert/strict";
import { workflowTools } from "../tools/builtin/workflows/index.js";
import { Logger } from "../util/logger.js";
import { SiteState } from "../site/state.js";
import type { ToolContext, ToolRegistrationOptions } from "../tools/types.js";

const logger = new Logger("silent");
function harness() {
  const siteState = new SiteState({ logger, timeoutMs: 5000, defaultAuth: { type: "api_key", key: "secret", username: "system" } });
  siteState.selectSite("https://forum.example.com");
  const ctx = { server: { registerTool() { return {} as never; } }, siteState, logger, maxReadLength: 50000 } as unknown as ToolContext;
  const opts: ToolRegistrationOptions = { allowWrites: true, toolsMode: "discourse_api_only", toolsets: ["workflows"] };
  const invoke = async (name: string, input: unknown) => {
    const tool = workflowTools.find((candidate) => candidate.name === name);
    assert.ok(tool, `missing tool ${name}`);
    return tool.handler(input as never, {} as never, ctx, opts);
  };
  return { invoke };
}
function body(result: any) { return JSON.parse(result.content[0].text); }

test("workflow list is slim and get adds a flat connection list", async () => {
  const original = globalThis.fetch; const urls: string[] = [];
  globalThis.fetch = async (input) => { const url = String(input); urls.push(url);
    if (url.includes("/workflows/12.json")) return Response.json({ workflow: { id: "12", name: "Full", nodes: [{ id: "a", name: "Start", type: "trigger:manual", parameters: { x: 1 } }, { id: "b", name: "Next", type: "action:log" }], connections: { Start: { main: [[{ node: "Next", type: "main", index: 0 }]] } }, pin_data: { Start: [] }, version_id: "v1" } });
    return Response.json({ workflows: [{ id: "12", name: "Full", nodes: [{ id: "a", name: "Start", type: "trigger:manual" }], connections: { huge: true }, static_data: { secret: <REDACTED> } }], meta: { total_rows_workflows: 1, load_more_workflows: "next" } });
  };
  try { const { invoke } = harness(); const listed = body(await invoke("discourse_list_workflows", { filter: "Full", cursor: "c" }));
    assert.equal(listed.workflows[0].connections, undefined); assert.deepEqual(listed.workflows[0].triggers, [{ id: "a", name: "Start", type: "trigger:manual" }]);
    assert.match(urls[0], /filter=Full/); assert.match(urls[0], /cursor=c/);
    const full = body(await invoke("discourse_get_workflow", { id: 12 })); assert.equal(full.version_id, "v1"); assert.equal(full.nodes[0].parameters.x, 1);
    assert.deepEqual(full.connection_list[0], { from: "Start", to: "Next", type: "main", output_index: 0, input_index: 0 });
  } finally { globalThis.fetch = original; }
});

test("workflow node catalog is slim unless an identifier is requested", async () => {
  const original = globalThis.fetch; globalThis.fetch = async () => Response.json({ node_types: [{ identifier: "condition:if", kind: "condition", label: "If", available: true, outputs: { true: {}, false: {} }, properties: [{ name: "leftValue" }], output_contracts: { true: { foo: "string" } }, examples: ["omit"] }] });
  try { const { invoke } = harness(); const slim = body(await invoke("discourse_list_workflow_node_types", {})); assert.deepEqual(slim.node_types[0].outputs, ["true", "false"]); assert.equal(slim.node_types[0].properties, undefined);
    const detail = body(await invoke("discourse_list_workflow_node_types", { identifier: "condition:if" })); assert.equal(detail.node_types[0].properties[0].name, "leftValue"); assert.equal(detail.node_types[0].examples, undefined);
  } finally { globalThis.fetch = original; }
});

test("workflow create converts flat connections and rejects an unpaired graph before HTTP", async () => {
  const original = globalThis.fetch; const requests: Array<{ method: string; body: any }> = [];
  globalThis.fetch = async (_input, init) => { requests.push({ method: init?.method ?? "GET", body: init?.body ? JSON.parse(String(init.body)) : undefined }); return Response.json({ workflow: { id: "1", name: "Small", nodes: [], connections: {} } }); };
  try { const { invoke } = harness(); const bad: any = await invoke("discourse_create_workflow", { name: "Bad", nodes: [] }); assert.equal(bad.isError, true); assert.equal(requests.length, 0);
    await invoke("discourse_create_workflow", { name: "Small", nodes: [{ id: "a", name: "Start", type: "trigger:manual" }, { id: "b", name: "Next", type: "action:log" }], connections: [{ from: "Start", to: "Next" }] });
    assert.deepEqual(requests[0].body.workflow.connections, { Start: { main: [[{ node: "Next", type: "main", index: 0 }]] } });
  } finally { globalThis.fetch = original; }
});

test("workflow update operations GET then PUT and publishing uses a separate body", async () => {
  const original = globalThis.fetch; const requests: Array<{ method: string; body: any }> = [];
  globalThis.fetch = async (_input, init) => { const method = init?.method ?? "GET"; const parsed = init?.body ? JSON.parse(String(init.body)) : undefined; requests.push({ method, body: parsed });
    if (method === "GET") return Response.json({ workflow: { id: "7", nodes: [{ id: "a", name: "Start", type: "trigger:manual" }], connections: {} } });
    return Response.json({ workflow: { id: "7", nodes: parsed.workflow.nodes ?? [], connections: parsed.workflow.connections ?? {}, published: parsed.workflow.published } });
  };
  try { const { invoke } = harness(); await invoke("discourse_update_workflow", { id: 7, operations: [{ op: "add_node", id: "b", node: { name: "Next", type: "action:log" } }, { op: "add_connection", from: "a", to: "b" }], published: true });
    assert.deepEqual(requests.map((request) => request.method), ["GET", "PUT", "PUT"]); assert.equal(requests[1].body.workflow.nodes.length, 2); assert.deepEqual(requests[2].body, { workflow: { published: true } });
  } finally { globalThis.fetch = original; }
});

test("workflow 404 gives the plugin/admin diagnostic", async () => {
  const original = globalThis.fetch; globalThis.fetch = async () => Response.json({ errors: ["not found"] }, { status: 404 });
  try { const result: any = await harness().invoke("discourse_get_workflow", { id: 99 }); assert.equal(result.isError, true); assert.match(body(result).error, /plugin disabled.*not found.*not admin/); }
  finally { globalThis.fetch = original; }
});
